 const format=p=>p.format||(/\/(shorts|reel|reels)\//.test(p.url||'')||p.platform==='tiktok'?'short':p.mediaType==='video'?(p.platform==='youtube'?'long':'video'):p.mediaType||'unknown');
 const tokens=s=>[...new Set(String(s||'').toLowerCase().match(/[\p{L}\p{N}#]{3,}/gu)||[])].filter(w=>!new Set('the and that this with from have your you for are was were what how can but not into they their our video videos reel reels shorts www com https about these those more just'.split(' ')).has(w));
